// Four-room office lightmap test for examples/tremor_lightmap.psh
//
// This is a compact, deliberately plain cousin of office.map. Broad pale
// surfaces make interpolation errors, seams, block boundaries and shadow
// defects conspicuous. Desks, partitions, cabinets and the stair landing give
// every room useful shadow edges without making the map visually busy.

spawn x=-7 y=1.6 z=-7 yaw=45
ambient brightness=0.20

// Outer shell: interior x/z -14..14, floor 0, ceiling 6.
box x0=-15 y0=-1 z0=-15 x1=15 y1=0 z1=15 tex=concrete_white top=carpet_beige scale=100
box x0=-15 y0=6 z0=-15 x1=15 y1=7 z1=15 tex=concrete_white bottom=ceiling_tile scale=160
box x0=-15 y0=0 z0=-15 x1=-14 y1=6 z1=15 tex=beigewall
box x0=14 y0=0 z0=-15 x1=15 y1=6 z1=15 tex=beigewall
box x0=-14 y0=0 z0=-15 x1=14 y1=6 z1=-14 tex=beigewall
box x0=-14 y0=0 z0=14 x1=14 y1=6 z1=15 tex=beigewall

// Two pale partitions form four offices. Each run has a broad doorway with a
// shallow lintel, making long uninterrupted walls around crisp shadow edges.
box x0=-0.25 y0=0 z0=-14 x1=0.25 y1=6 z1=-9 tex=beigewall
box x0=-0.25 y0=3.2 z0=-9 x1=0.25 y1=6 z1=-5 tex=beigewall
box x0=-0.25 y0=0 z0=-5 x1=0.25 y1=6 z1=5 tex=beigewall
box x0=-0.25 y0=3.2 z0=5 x1=0.25 y1=6 z1=9 tex=beigewall
box x0=-0.25 y0=0 z0=9 x1=0.25 y1=6 z1=14 tex=beigewall

box x0=-14 y0=0 z0=-0.25 x1=-9 y1=6 z1=0.25 tex=beigewall
box x0=-9 y0=3.2 z0=-0.25 x1=-5 y1=6 z1=0.25 tex=beigewall
box x0=-5 y0=0 z0=-0.25 x1=5 y1=6 z1=0.25 tex=beigewall
box x0=5 y0=3.2 z0=-0.25 x1=9 y1=6 z1=0.25 tex=beigewall
box x0=9 y0=0 z0=-0.25 x1=14 y1=6 z1=0.25 tex=beigewall

// Each fluorescent panel is itself an area light. `emit=bottom` selects only
// its downward face, makes that face full-bright, and samples it on a grid.
box x0=-7.4 y0=5.84 z0=-8.6 x1=-6.6 y1=5.98 z1=-5.4 tex=metal_dark bottom=light_bank emit=bottom brightness=1.8 reach=12 emit_spacing=0.8 fit
box x0=6.6 y0=5.84 z0=-8.6 x1=7.4 y1=5.98 z1=-5.4 tex=metal_dark bottom=light_bank emit=bottom brightness=1.8 reach=12 emit_spacing=0.8 fit
box x0=-7.4 y0=5.84 z0=5.4 x1=-6.6 y1=5.98 z1=8.6 tex=metal_dark bottom=light_bank emit=bottom brightness=1.8 reach=12 emit_spacing=0.8 fit
box x0=6.6 y0=5.84 z0=5.4 x1=7.4 y1=5.98 z1=8.6 tex=metal_dark bottom=light_bank emit=bottom brightness=1.8 reach=12 emit_spacing=0.8 fit

// Northwest: a small open office with two desks, monitors and filing units.
box x0=-12.5 y0=0 z0=-11.8 x1=-8.5 y1=0.86 z1=-10.5 tex=metal_01 top=wood
box x0=-11.6 y0=0.86 z0=-10.8 x1=-10.8 y1=1.55 z1=-10.64 tex=metal_dark nz=monitor light=13 fit
box x0=-9.9 y0=0.86 z0=-10.8 x1=-9.1 y1=1.55 z1=-10.64 tex=metal_dark nz=monitor light=13 fit
box x0=-12.5 y0=0 z0=-6.5 x1=-8.5 y1=0.86 z1=-5.2 tex=metal_01 top=wood
box x0=-11.6 y0=0.86 z0=-6.36 x1=-10.8 y1=1.55 z1=-6.2 tex=metal_dark pz=monitor light=13 fit
box x0=-9.9 y0=0.86 z0=-6.36 x1=-9.1 y1=1.55 z1=-6.2 tex=metal_dark pz=monitor light=13 fit
box x0=-4.6 y0=0 z0=-12.8 x1=-2.4 y1=2.2 z1=-11.5 tex=concrete_white px=metal_panels fit
box x0=-4.6 y0=0 z0=-4.8 x1=-2.4 y1=1.4 z1=-3.5 tex=concrete_white px=metal_panels fit

// Northeast: a meeting room with a long table, chairs and a pale presentation wall.
box x0=3.0 y0=1.05 z0=-8.8 x1=11.0 y1=1.35 z1=-5.2 tex=wood top=marble_white scale=90
box x0=3.4 y0=0 z0=-8.4 x1=3.9 y1=1.05 z1=-7.9 tex=metal_01
box x0=10.1 y0=0 z0=-8.4 x1=10.6 y1=1.05 z1=-7.9 tex=metal_01
box x0=3.4 y0=0 z0=-6.1 x1=3.9 y1=1.05 z1=-5.6 tex=metal_01
box x0=10.1 y0=0 z0=-6.1 x1=10.6 y1=1.05 z1=-5.6 tex=metal_01
box x0=6.1 y0=0 z0=-10.2 x1=7.9 y1=0.75 z1=-9.2 tex=metal_01 top=carpet_blue
box x0=6.1 y0=0 z0=-4.8 x1=7.9 y1=0.75 z1=-3.8 tex=metal_01 top=carpet_blue
box x0=13.75 y0=1.2 z0=-10.8 x1=13.9 y1=4.4 z1=-3.2 tex=concrete_white nx=marble_white light=11 fit

// Southwest: broad white stairs climb to a simple inspection mezzanine.
box x0=-12.5 y0=0 z0=2.0 x1=-9.0 y1=0.25 z1=2.6 tex=concrete_white top=marble_white scale=90
box x0=-12.5 y0=0 z0=2.6 x1=-9.0 y1=0.50 z1=3.2 tex=concrete_white top=marble_white scale=90
box x0=-12.5 y0=0 z0=3.2 x1=-9.0 y1=0.75 z1=3.8 tex=concrete_white top=marble_white scale=90
box x0=-12.5 y0=0 z0=3.8 x1=-9.0 y1=1.00 z1=4.4 tex=concrete_white top=marble_white scale=90
box x0=-12.5 y0=0 z0=4.4 x1=-9.0 y1=1.25 z1=5.0 tex=concrete_white top=marble_white scale=90
box x0=-12.5 y0=0 z0=5.0 x1=-9.0 y1=1.50 z1=5.6 tex=concrete_white top=marble_white scale=90
box x0=-12.5 y0=0 z0=5.6 x1=-9.0 y1=1.75 z1=6.2 tex=concrete_white top=marble_white scale=90
box x0=-12.5 y0=0 z0=6.2 x1=-9.0 y1=2.00 z1=6.8 tex=concrete_white top=marble_white scale=90
box x0=-13.2 y0=1.75 z0=6.8 x1=-8.3 y1=2.0 z1=12.5 tex=concrete_white top=carpet_blue bottom=ceiling_tile scale=100
box x0=-8.45 y0=2.0 z0=6.8 x1=-8.3 y1=3.0 z1=12.5 tex=metal_01 top=wood
box x0=-7.2 y0=0 z0=9.2 x1=-4.0 y1=1.05 z1=12.0 tex=metal_01 top=wood
box x0=-6.4 y0=1.05 z0=11.45 x1=-5.6 y1=1.7 z1=11.6 tex=metal_dark nz=monitor light=13 fit

// Southeast: low partitions and storage make long, clean-edged shadows.
box x0=4.0 y0=0 z0=4.0 x1=4.18 y1=2.1 z1=11.8 tex=concrete_white px=beigewall fit
box x0=9.82 y0=0 z0=4.0 x1=10.0 y1=2.1 z1=11.8 tex=concrete_white nx=beigewall fit
box x0=4.18 y0=0.95 z0=9.0 x1=9.82 y1=1.2 z1=11.2 tex=wood top=marble_white scale=90
box x0=4.5 y0=0 z0=9.3 x1=5.0 y1=0.95 z1=9.8 tex=metal_01
box x0=9.0 y0=0 z0=9.3 x1=9.5 y1=0.95 z1=9.8 tex=metal_01
box x0=4.5 y0=0 z0=10.4 x1=5.0 y1=0.95 z1=10.9 tex=metal_01
box x0=9.0 y0=0 z0=10.4 x1=9.5 y1=0.95 z1=10.9 tex=metal_01
box x0=11.2 y0=0 z0=3.0 x1=13.0 y1=2.4 z1=5.0 tex=concrete_white nx=metal_panels fit
box x0=11.2 y0=0 z0=6.0 x1=13.0 y1=3.2 z1=8.0 tex=concrete_white nx=metal_panels fit

// A slim structural column beside the southeast doorway provides a curved
// sequence of lightmap gradients without blocking circulation.
prism cx=2.2 cz=2.2 radius=0.75 y0=0 y1=4.8 sides=8 rot=22.5 tex=concrete_white
